2^{a-2} &= 2^{b}  \\
k &= 10x + 5\cdot 2^{b} - 5(2^{b} - k_{\text{odd}}) \\
\boxed{k} &= 10x + 5\cdot 2^{b} + 5k_{\text{odd}} \\
\text{must be even} &&\text{(needs factors of $2$ to form $5^2$ along with $3^b$ from $x$)} \\
